/**
 * One entry of a timeline (B4b, spec/02 §3.18): [date] (caption textMuted, tabular, a 112 dp column that grows with
 * the text; on its own line above once the title would be narrower than that column), the kind as a 16 dp [icon] in textMuted, [title] in label at body weight, an optional [meta] line. A 1 dp
 * border hairline above ([hairline] = false for the first entry), no vertical stroke. [warning] = an event that asks
 * for something: the warning glyph in warning, the title is its word („Konflikt“). [onClick] makes the whole entry the
 * target (opens its version): hover and pressed fills, the inset focus ring. At least 48 dp.
 */
@Composable
fun SbTimelineEntry(
    date: String,
    title: String,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    meta: String? = null,
    warning: Boolean = false,
    onClick: (() -> Unit)? = null,
    hairline: Boolean = true,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val tabular = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val fill = when {
        onClick == null -> Color.Transparent
        pressed -> c.pressedFill
        hovered -> c.hoverFill
        else -> Color.Transparent
    }
    val target = if (onClick == null) {
        Modifier.semantics(mergeDescendants = true) { }
    } else {
        Modifier
            .sbFocusRingInset(interaction)
            .clickable(interactionSource = interaction, indication = null, role = Role.Button, onClick = onClick)
    }
    BoxWithConstraints(
        modifier
            .fillMaxWidth()
            .heightIn(min = t.size.controlMd)
            .background(fill)
            .drawBehind {
                if (hairline) drawRect(c.border, Offset.Zero, Size(size.width, t.borderWidth.hairline.toPx()))
            }
            .then(target)
            .padding(horizontal = t.space.s2, vertical = t.space.s1),
    ) {
        // the web's 7rem column grows with the text; once the title would be narrower than it (large text on a
        // phone), the date stands on its own line above glyph and title (D99 (1): the place grows, words stay whole)
        val column = (t.space.s16 + t.space.s12) * sbTextScale()
        val stacked = maxWidth - column - t.size.iconSm - t.space.s2 * 2 < column
        if (stacked) {
            Column {
                Text(date, style = tabular, color = c.textMuted)
                Row(horizontalArrangement = Arrangement.spacedBy(t.space.s2)) {
                    SbTimelineMark(warning, icon)
                    SbTimelineMain(title, meta, Modifier.weight(1f))
                }
            }
        } else {
            Row(horizontalArrangement = Arrangement.spacedBy(t.space.s2)) {
                Text(date, style = tabular, color = c.textMuted, modifier = Modifier.width(column))
                SbTimelineMark(warning, icon)
                SbTimelineMain(title, meta, Modifier.weight(1f))
            }
        }
    }
}

/** The kind of a timeline entry: the 16 dp glyph, 2 dp down; the warning glyph in warning for [warning]; hidden. */
@Composable
private fun SbTimelineMark(warning: Boolean, icon: ImageVector?) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    Box(Modifier.padding(top = t.space.s0_5).size(t.size.iconSm)) {
        when {
            warning -> Icon(SebaroIcons.Outline16.Warning, contentDescription = null, tint = c.warning, modifier = Modifier.size(t.size.iconSm))
            icon != null -> Icon(icon, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconSm))
        }
    }
}

/** The title of a timeline entry in label at body weight and its optional meta line (caption textMuted, tabular). */
@Composable
private fun SbTimelineMain(title: String, meta: String?, modifier: Modifier) {
    val c = SebaroTheme.colors
    val ty = SebaroTheme.typography
    Column(modifier) {
        Text(title, style = ty.label.copy(fontWeight = ty.body.fontWeight), color = c.text)
        if (meta != null) Text(meta, style = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings), color = c.textMuted)
    }
}
